"use client"

import { Monitor, Moon, Sun } from "lucide-react"
import { useTranslations } from "next-intl"
import { useTheme } from "next-themes"
import { useEffect, useState } from "react"

import { Button } from "@workspace/ui/components/button"
import {
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
} from "@workspace/ui/components/dropdown-menu"

const THEMES = [
  { icon: Sun, value: "light" },
  { icon: Moon, value: "dark" },
  { icon: Monitor, value: "system" },
] as const

type ThemeMode = (typeof THEMES)[number]["value"]

export function ThemeSwitcher() {
  const t = useTranslations("shell.theme")
  const { setTheme, theme } = useTheme()
  const [mounted, setMounted] = useState(false)

  useEffect(() => setMounted(true), [])

  const current = (THEMES.find((item) => item.value === theme)?.value ??
    "system") satisfies ThemeMode
  const currentIndex = THEMES.findIndex((item) => item.value === current)
  const CurrentIcon = mounted ? THEMES[currentIndex].icon : Monitor

  return (
    <Button
      aria-label={`${t("label")}: ${t(current)}`}
      size="icon-sm"
      variant="ghost"
      onClick={() =>
        setTheme(THEMES[(currentIndex + 1) % THEMES.length].value)
      }
    >
      <CurrentIcon />
    </Button>
  )
}

export function ThemeMenuItem() {
  const t = useTranslations("shell.theme")
  const { setTheme, theme } = useTheme()
  const current = (THEMES.find((item) => item.value === theme)?.value ??
    "system") satisfies ThemeMode
  const CurrentIcon =
    THEMES.find((item) => item.value === current)?.icon ?? Monitor

  return (
    <DropdownMenuSub>
      <DropdownMenuSubTrigger>
        <CurrentIcon aria-hidden="true" />
        {t("label")}
      </DropdownMenuSubTrigger>
      <DropdownMenuSubContent>
        <DropdownMenuRadioGroup onValueChange={setTheme} value={current}>
          {THEMES.map(({ icon: Icon, value }) => (
            <DropdownMenuRadioItem key={value} value={value}>
              <Icon aria-hidden="true" />
              {t(value)}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuSubContent>
    </DropdownMenuSub>
  )
}

